$('#moonlightStudy').onclick=()=>{lightingStudy=true;chooseScene(11,true);};$('#moonlightBefore').onclick=()=>chooseScene(11,true);$('#moonlightAfter').onclick=()=>chooseScene(12,true);$('#moonlightExit').onclick=()=>{lightingStudy=false;renderScene();};
$('#startTour').onclick=startTour;$('#fullPreview').onclick=()=>chooseScene(30,true);$('#tourPlay').onclick=()=>{if(tourTimer)stopTour();else startTour();};$('#tourPrev').onclick=()=>chooseScene((scenePreview??0)-1);$('#tourNext').onclick=()=>chooseScene((scenePreview??0)+1);$('#tourEnd').onclick=()=>chooseScene(30);$('#tourExit').onclick=()=>chooseScene(null);
$('#scenePreview').onchange=e=>chooseScene(e.target.value===''?null:+e.target.value,true);$('#previewPrev').onclick=()=>chooseScene((scenePreview??totals(state).lit)-1,true);$('#previewNext').onclick=()=>chooseScene((scenePreview??totals(state).lit)+1,true);
$('#deviceSteps').oninput=e=>{state.device[current()]=cleanSteps(e.target.value);persist();};$('#demoSecret').onclick=()=>{if(!qualifySecret(state.device[current()]||0)){toast('Demo: enter 20,000 simulated device steps first.');return;}state.secret=true;persist();renderScene();chime('secret');$('#world').scrollIntoView({behavior:'smooth',block:'start'});toast('A golden key glints by the oak.');};
function openRoom(){if(!state.secret&&!previewSecret())return;stopTour();if(!roomPreview){state.roomOpened=true;persist();}renderScene();$('#roomDialog').showModal();if(!state.fireMuted)startFire();}$('#goldenKey').onclick=openRoom;$('#secretDoor').onclick=openRoom;
let fireAudio=null,firePlaying=false;
function fireUI(){const b=$('#kettleBtn');b.textContent=firePlaying?'Mute fireplace':'Unmute fireplace';b.setAttribute('aria-pressed',String(firePlaying));}
function stopFire(){if(fireAudio)fireAudio.pause();firePlaying=false;fireUI();}
async function startFire(){fireAudio??=new Audio('assets/fireplace-recorded.mp3');fireAudio.loop=true;fireAudio.volume=.4;try{await fireAudio.play();if(!$('#roomDialog').open){stopFire();return;}firePlaying=true;fireUI();}catch{fireUI();toast('Your browser needs a tap on Unmute fireplace to allow audio.');}}
$('#kettleBtn').onclick=()=>{state.fireMuted=firePlaying;persist();if(firePlaying)stopFire();else startFire();};
$('#roomPreviewBtn').onclick=()=>{roomPreview=true;openRoom();};
$('#roomDialog').addEventListener('close',()=>{stopFire();roomPreview=false;renderScene();});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopFire();else if($('#roomDialog').open&&!state.fireMuted)startFire();});
$('#endingRoom').onclick=()=>{$('#world').scrollIntoView({behavior:'smooth',block:'start'});highlight(sceneFor(30));};
$('#journeyBtn').onclick=()=>{const n=scenePreview??totals(state).lit,list=[];if(n>=1)list.push(['✦','The path lanterns',`${Math.min(n,6)} little lights along the path`]);if(n>=11)list.push(['♧','A garden visitor','The fox has arrived']);if(n>=14)list.push(['☁','A warm cottage','Chimney smoke in the evening']);if(n>=22)list.push(['✧','A shooting star','Watch the sky']);if(state.secret||previewSecret())list.push(['⚿','The golden key',state.roomOpened?'The fox’s room is open':'Something waits behind the oak door']);$('#discoveryList').innerHTML=list.length?list.map(a=>`<div class="discovery-item"><i>${a[0]}</i><div>${a[1]}<span>${a[2]}</span></div></div>`).join(''):'<p class="muted">Light your first lantern to begin.</p>';$('#discoveriesDialog').showModal();};
$('#resetBtn').onclick=()=>{if(!confirm('Reset all saved steps and discoveries in this prototype?'))return;stopTour();state=initialState();sound=false;preview=null;scenePreview=null;$('#previewDay').value='';$('#scenePreview').value='';persist();soundUI();render();};
soundUI();render();if(!storageOK)toast('Progress may not be saved between visits.');
